// Generate src/api/schema.d.ts from the exported OpenAPI file (docs/openapi.json).
//   npm run api:generate   write the file
//   npm run api:check      fail when the committed file is stale (CI and pre-commit)
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'

const source = fileURLToPath(new URL('../../docs/openapi.json', import.meta.url))
const target = fileURLToPath(new URL('../src/api/schema.d.ts', import.meta.url))

const header =
  '/* eslint-disable */\n// Generated by scripts/generate-api.mjs from docs/openapi.json. Do not edit.\n\n'
const ast = await openapiTS(JSON.parse(readFileSync(source, 'utf8')))
const generated = header + astToString(ast)

if (process.argv.includes('--check')) {
  let current = ''
  try {
    current = readFileSync(target, 'utf8')
  } catch {
    // missing file counts as stale
  }
  if (current.replace(/\r\n/g, '\n') !== generated.replace(/\r\n/g, '\n')) {
    console.error('src/api/schema.d.ts is stale: run `npm run api:generate` and commit the result.')
    process.exit(1)
  }
  console.log('API schema is up to date.')
} else {
  writeFileSync(target, generated)
  console.log(`wrote ${target}`)
}
